     1	# Marketplace feed
     2	
     3	Products with marketplace: true are syndicated to the marketplace. The marketplace requires every
     4	listed item to ship within 2 business days; listing an item we can't ship gets the seller account
     5	suspended.

--- docs/warehouse-api.md ---
     1	# Warehouse partner API
     2	
     3	We PUT /stock with [{sku, quantity}] every five minutes. quantity must be an integer >= 0. The
     4	partner rejects the whole batch, for every SKU, if any value is negative or not an integer.

--- src/coupons.js ---
     1	function apply(subtotal, coupon) {
     2	  return coupon && coupon.percent ? Math.round(subtotal * (1 - coupon.percent / 100)) : subtotal;
     3	}
     4	
     5	module.exports = { apply };

--- src/inventory.js ---
     1	const stock = new Map([
     2	  ['sku-1', { onHand: 12, reserved: 2 }],
     3	  ['sku-2', { onHand: 0, reserved: 0 }],
     4	]);
     5	
     6	function available(sku) {
     7	  const s = stock.get(sku);
     8	  return s ? s.onHand - s.reserved : 0;
     9	}
    10	
    11	function reserve(sku, qty) {
    12	  if (available(sku) < qty) throw new Error('out of stock: ' + sku);
    13	  stock.get(sku).reserved += qty;
    14	}
    15	
    16	module.exports = { stock, available, reserve };

--- src/loyalty.js ---
     1	function points(subtotal) {
     2	  return Math.floor(subtotal / 100);
     3	}
     4	
     5	module.exports = { points };

--- src/orders.js ---
     1	const { reserve } = require('./inventory');
     2	const { estimateTax } = require('./tax');
     3	
     4	function placeOrder(cart) {
     5	  for (const line of cart.lines) reserve(line.sku, line.qty);
     6	  return { lines: cart.lines, subtotal: cart.subtotal, address: cart.address, tax_estimate: estimateTax(cart) };
     7	}
     8	
     9	module.exports = { placeOrder };

--- src/recommendations.js ---
     1	function related(sku) {
     2	  return sku === 'sku-1' ? ['sku-2'] : [];
     3	}
     4	
     5	module.exports = { related };

--- src/search.js ---
     1	function match(products, q) {
     2	  return products.filter((p) => p.title.toLowerCase().includes(q.toLowerCase()));
     3	}
     4	
     5	module.exports = { match };

--- src/shipments.js ---
     1	const { estimateTax } = require('./tax');
     2	
     3	function ship(order, shippedAt = new Date()) {
     4	  return { ...order, shippedAt: shippedAt.toISOString(), tax: estimateTax(order) };
     5	}
     6	
     7	module.exports = { ship };

--- src/tax.js ---
     1	const RATES = { CA: 0.0725, NY: 0.04, TX: 0.0625 };
     2	
     3	function estimateTax(order) {
     4	  return Math.round(order.subtotal * (RATES[order.address.state] ?? 0));
     5	}
     6	
     7	module.exports = { estimateTax };

--- src/marketplace/feed.js ---
     1	const flags = require('../../config/flags.json');
     2	
     3	function feedItems(products) {
     4	  if (!flags.marketplace_feed) return [];
     5	  return products.filter((p) => p.marketplace).map((p) => ({ sku: p.sku, title: p.title, price: p.price }));
     6	}
     7	
     8	module.exports = { feedItems };

--- src/warehouse/sync.js ---
     1	const { stock, available } = require('../inventory');
     2	
     3	function payload() {
     4	  return [...stock.keys()].map((sku) => ({ sku, quantity: available(sku) }));
     5	}
     6	
     7	module.exports = { payload };

--- test/warehouse-sync.test.js ---
     1	const test = require('node:test');
     2	const assert = require('node:assert');
     3	const { payload } = require('../src/warehouse/sync');
     4	
     5	test('stock sent to the partner is a non-negative integer for every sku', () => {
     6	  for (const row of payload()) assert.ok(Number.isInteger(row.quantity) && row.quantity >= 0, row.sku);
     7	});

